package com.andye.warmod.antiair.network;import net.fabricmc.fabric.api.networking.v1.*;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.server.level.ServerLevel;public final class AntiAirNetworking{private static boolean registered;private AntiAirNetworking(){}public static void register(){if(registered)return;PayloadTypeRegistry.clientboundPlay().register(ClientboundAntiAirLaunchPayload.TYPE,ClientboundAntiAirLaunchPayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundAntiAirRouteLockPayload.TYPE,ClientboundAntiAirRouteLockPayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundAntiAirPhasePayload.TYPE,ClientboundAntiAirPhasePayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundAntiAirRemovePayload.TYPE,ClientboundAntiAirRemovePayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundAntiAirDetonationPayload.TYPE,ClientboundAntiAirDetonationPayload.STREAM_CODEC);registered=true;}public static void send(ServerLevel l,CustomPacketPayload p){for(var player:PlayerLookup.level(l))ServerPlayNetworking.send(player,p);}}